param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath,[Parameter(Mandatory=$true)][string]$HypervisorCMake,[Parameter(Mandatory=$true)][string]$TestsCMake,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';function A($x,$m){if(-not $x){throw $m}};function V($s,$h,$t,$hc,$tc){foreach($x in @('VmxCr3RouteExecute(','writes guest CR3, advances guest RIP, then commits','never commits','publishes exact','partial-write diagnostics')){A($h.Contains($x))"header $x"};foreach($x in @('VmxCr3RouteOwnerValidateBinding(Owner) != VMX_CR3_TARGET_OK','Separate(Owner->States, Owner->StatesBytes','VmxCr3RouteOwnerPlan(Owner, ProcessorIndex','Write(WriteContext, VMCS_GUEST_CR3, Plan.GuestCr3)','VMX_CR3_ROUTE_EXECUTION_CR3_WRITE_FAILED, 1, VMCS_GUEST_CR3','Write(WriteContext, VMCS_GUEST_RIP, Plan.AdvancedRip)','VMX_CR3_ROUTE_EXECUTION_RIP_WRITE_FAILED, 2, VMCS_GUEST_RIP','VmxCr3RouteOwnerCommit(Owner, ProcessorIndex, &Plan)','VMX_CR3_ROUTE_EXECUTION_COMMIT_FAILED, 2, 0','Staged.StateCommitted = 1','*OutExecution = Staged')){A($s.Contains($x))"source $x"};A($s-notmatch '(?i)ntddk|wdm\.h|wdf\.h|__vmx|vmread|invept|IOCTL|Dispatcher')'pure';foreach($x in @('write order and values','commit selected processor','write failure preserves residency','write failure diagnostics','stop after failed write','planning failure no write no output','state output alias rejected','state output alias preserves owner')){A($t.Contains($x))"test $x"};A(([regex]::Matches($hc,'(?m)^\s*vmx_cr3_route_executor\.c\s*$')).Count-eq1)'source once';A(([regex]::Matches($tc,'add_test\(NAME test_vmx_cr3_route_executor COMMAND')).Count-eq1)'unit once';A(([regex]::Matches($tc,'test_vmx_cr3_route_executor_contracts')).Count-eq1)'contract once'}
$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$t=Get-Content -Raw $TestPath;$hc=Get-Content -Raw $HypervisorCMake;$tc=Get-Content -Raw $TestsCMake;V $s $h $t $hc $tc;foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch 'VmxCr3RouteExecute|vmx_cr3_route_executor')"unwired $p"};$m=@($s.Replace('VmxCr3RouteOwnerValidateBinding(Owner) != VMX_CR3_TARGET_OK','0'),$s.Replace('Separate(Owner->States, Owner->StatesBytes','Separate(NULL, Owner->StatesBytes'),$s.Replace('VmxCr3RouteOwnerPlan(Owner, ProcessorIndex','VmxCr3RouteOwnerPlan(Owner, 0'),$s.Replace('Write(WriteContext, VMCS_GUEST_CR3, Plan.GuestCr3)','1'),$s.Replace('VMX_CR3_ROUTE_EXECUTION_CR3_WRITE_FAILED, 1, VMCS_GUEST_CR3','VMX_CR3_ROUTE_EXECUTION_CR3_WRITE_FAILED, 0, 0'),$s.Replace('Write(WriteContext, VMCS_GUEST_RIP, Plan.AdvancedRip)','1'),$s.Replace('VMX_CR3_ROUTE_EXECUTION_RIP_WRITE_FAILED, 2, VMCS_GUEST_RIP','VMX_CR3_ROUTE_EXECUTION_RIP_WRITE_FAILED, 1, 0'),$s.Replace('VmxCr3RouteOwnerCommit(Owner, ProcessorIndex, &Plan)','VMX_CR3_TARGET_OK'),$s.Replace('Staged.StateCommitted = 1','Staged.StateCommitted = 0'),$s.Replace('*OutExecution = Staged','memset(OutExecution,0,sizeof(*OutExecution))'));$i=0;foreach($x in $m){$i++;A($x-ne$s)"vacuous $i";$bad=$false;try{V $x $h $t $hc $tc}catch{$bad=$true};A($bad)"accepted $i"};Write-Host 'PASS: CR3 route executor writes CR3 then RIP, commits only after both writes, publishes partial failure diagnostics, and is wired only through the authenticated persistent dispatcher route.'
